ssl_ctx = ssl.create_default_context()
ssl_ctx.check_hostname = False
ssl_ctx.verify_mode = ssl.CERT_NONE

def google_search(query):
    try:
        url = 'https://www.google.com/search?q=' + urllib.request.quote(query) + '&tbm=nws&hl=zh-CN'
        req = urllib.request.Request(url, headers={
            'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36',
            'Accept-Language': 'zh-CN,zh;q=0.9'
        })
        resp = urllib.request.urlopen(req, context=ssl_ctx, timeout=10)
        html = resp.read().decode('utf-8', errors='ignore')
        results = re.findall(r'<h3[^>]*>([^<]+)</h3>', html)
        return results[:8] if results else ['(无结果)']
    except Exception as e:
        return [f'ERROR: {str(e)[:80]}']

queries = {
    '国际': '今日国际新闻 头条 2026年5月',
    '国内': '今日热搜 头条 2026年5月23日',
    '科技': 'AI 科技新闻 今日 2026年5月',
    'ACG': '动漫游戏 今日新闻 2026年5月'
}

for cat, q in queries.items():
    print(f'\n=== {cat} ===')
    results = google_search(q)
    for r in results:
        print(f'  • {r}')
"}

